        XCTAssertEqual(o["cut2"] as? String, "Cumaru · Arauco Trend")
        XCTAssertEqual(o["f3"] as? String, "#716c69|duratex-cinza-sagrado-essencial", "fita na cor de fora do caixote quando configurado")
