        XCTAssertEqual(o["f5"] as? String, "#716c69|duratex-cinza-sagrado-essencial")
        XCTAssertEqual(o["f6"] as? String, "#b49c7d|arauco-cumaru-trend", "tirar a pintura das fitas volta pro padrão")
