          var x=0;[983.5,983.5,983.5,983.5].forEach(function(w,i){var a={id:100+i,liso:true,x:x,b:0,w:w,h:2600,jt:{t:'reb',w:15,d:6}};if(Math.min(800,x+w)-Math.max(0,x)>1)a.rc={op:9,f:0};S.rp.push(a);x+=w+15});draw();
