          document.querySelector('#rpsabar [data-sab="go"]').click();R.criado=S.rp.map(function(a){return a.x+'+'+a.w+' b'+a.b+' h'+a.h+(a.liso?' liso':' ripado')}).join();R.fechou=!window.RPSA&&document.getElementById('rpsabar').hidden;
