          window.MINI3OFF=1;PR.setupDone=1;var R={};
          S.room='sala';S.env='livre';S.W=6000;S.H=3215;S.Hm=1;S.Wm=1;S.mods=[];S.fr=[];S.rp=[];S.isl=[];S.ops=[];S.stones=[];S.st=null;S.m=null;draw();
