          R.recebido=!!window.RO&&S.mods.length===1;R.tudo=S.mods.every(function(m){return m.lock})&&S.rp.every(function(a){return a.lock})&&S.fr.every(function(f){return f.lock})&&S.ops.every(function(x){return x.lk===1});
