          window.MINI3OFF=1;PR.setupDone=1;window.toast=function(){};S.mods=[];S.stones=[];S.fr=[];S.rp=[];S.ops=[];S.env='sala';S.room='sala';S.Hm=1;var R={},F=[],N=0,r1=function(v){return Math.round(v*10)/10};
