          var g=S.geo[0],x0=g.x,z0=g.z,r=col.getBoundingClientRect(),X=r.left+r.width/2,Y=r.top+r.height/2;pe(col,'pointerdown',X,Y);for(var k=1;k<=6;k++)pe(A,'pointermove',X-k*8,Y);pe(A,'pointerup',X-48,Y);
