          var sv=document.getElementById('svg'),q=function(){return [].slice.call(sv.querySelectorAll('[data-s]'))};R.tem=q().length;R.fechada=q().map(function(e){return e.style.pointerEvents+'/'+(e.style.display||'')}).join(',');
