    /// Parede sem espaço: o módulo novo não entra espremido com porta de 5 cm; avisa e não cria. Os que já existem ficam.
    func testModuloNovoNaoEntraEspremidoComPortaMinuscula() async throws {
        let web = try await editor()
        let o = try await run(web, #"""
          var W=function(ms){return new Promise(function(r){setTimeout(r,ms)})};window.MINI3OFF=1;PR.setupDone=1;var R={};var TL=[];var t0=window.toast;window.toast=toast=function(m){TL.push(String(m));try{return t0.apply(this,arguments)}catch(_){}};
          var cid=null,ix=-1;CATS.forEach(function(c){(c.it||[]).forEach(function(it,i){if(cid===null&&/^Guarda-roupa 3 vãos/.test(it.n||'')){cid=c.id;ix=i}})});
          var add=async function(){CATALL=true;catOpen(cid);await W(80);document.querySelector('#catm [data-cati="'+cid+'|'+ix+'"]').click();await W(250)};
          S.env='livre';S.room='quarto';S.W=3200;S.mods=[];S.stones=[];draw();
          newTpl(CATS[0].it[0]);var a=S.mods[0];a.x=0;a.w=2765;a.meu=1;draw();var n0=S.mods.length;TL=[];
          await add();var nv=S.mods.filter(function(m){return !m.meu});R.apertado=nv.length+' novo'+nv.map(function(m){return ' · '+(m.wing||'fundo')+' w='+m.w+' menor porta '+Math.min.apply(null,partsOf(m).filter(function(p){return p.name==='Porta'}).map(function(p){return Math.round(p.w)}))}).join('')+' · aviso='+TL.some(function(t){return /Não tem espaço livre|parede do lado/.test(t)});
          S.mods=[a];a.w=600;draw();TL=[];await add();var g=S.mods.filter(function(m){return !m.meu})[0];R.normal=g?('w='+g.w+' · menor porta '+Math.min.apply(null,partsOf(g).filter(function(p){return p.name==='Porta'}).map(function(p){return Math.round(p.w)}))):'não entrou';
          R.existente=S.mods.indexOf(a)>=0&&a.w===600;R.errs=window.__errs||[];return JSON.stringify(R);
          """#)
        XCTAssertEqual(o["apertado"] as? String, "0 novo · aviso=true", "antes entrava com 335 mm e portas de 48 a 52 mm")
        XCTAssertEqual(o["normal"] as? String, "w=2500 · menor porta 409")
        XCTAssertEqual(o["existente"] as? Bool, true)
        XCTAssertEqual((o["errs"] as? [Any])?.count ?? 0, 0, "sem erros: \(o["errs"] ?? "")")
    }

    /// Projeto antigo: um botão corrige de uma vez os módulos com divisória na beira. Sem o toque nada muda; a versão de antes fica no Histórico.
    func testProjetoAntigoCorrigeDivisoriasNaBeiraComUmToque() async throws {
        let web = try await editor()
        let o = try await run(web, #"""
          try{STD().supPedra=0}catch(_){}
          var W=function(ms){return new Promise(function(r){setTimeout(r,ms)})};window.MINI3OFF=1;PR.setupDone=1;var R={};
          var p=newProjFor({nome:'Projeto Antigo'});S.mods=[];
          /* projeto antigo: 3 aéreos, 2 com divisória na beira (95% e 5%) e prateleira, 1 certo com divisória no meio */
          for(var i=0;i<3;i++){newTpl(CATS[1].it[2]);}S.mods.forEach(function(m,i){m.x=i*700;m.w=666.8;m.shv=[.5];m.div=[i===0?0.95:i===1?0.05:0.5];m.v.push(JSON.parse(JSON.stringify(m.v[0])))});draw();saveNow();
          var res=function(){return S.mods.map(function(m){var P=partsOf(m);return 'div'+JSON.stringify(m.div)+' v'+m.v.length+' prat '+P.filter(function(q){return /^Prateleira/.test(q.name)}).map(function(q){return Math.round(q.w)}).join('/')+' porta mín '+Math.min.apply(null,P.filter(function(q){return q.name==='Porta'}).map(function(q){return Math.round(q.w)}))}).join(' || ')};
          R.antes=res();var b=document.getElementById('pfixbar');R.faixa=b&&!b.hidden?b.textContent.slice(0,24):'sem faixa';
          /* abrir, desenhar e gravar não corrige sozinho */
          draw();saveNow();await W(700);R.sozinho=res()===R.antes;
          var h0=projHist.list(CUR).length;await W(700);try{histTick()}catch(_){}
          document.querySelector('[data-pfix]').click();await W(200);
          R.depois=res();b=document.getElementById('pfixbar');R.faixaSome=!b||b.hidden;R.hist=projHist.list(CUR).length>h0;
          await W(700);try{histTick()}catch(_){}document.getElementById('und').click();await W(120);R.desfez=res()===R.antes;
          /* módulo travado fica de fora */
          S.mods[0].lock=true;draw();R.travado=(document.getElementById('pfixbar').textContent.match(/[0-9]+ módulo/)||[''])[0];
          R.errs=window.__errs||[];return JSON.stringify(R);
          """#)
        XCTAssertEqual(o["antes"] as? String, "div[0.95] v2 prat 597/24 porta mín 17 || div[0.05] v2 prat 24/597 porta mín 17 || div[0.5] v2 prat 311/311 porta mín 160")
        XCTAssertEqual(o["faixa"] as? String, "⚠ 2 módulo(s) com divisó")
        XCTAssertEqual(o["sozinho"] as? Bool, true, "abrir, desenhar e gravar não corrige sozinho")
        XCTAssertEqual(o["depois"] as? String, "div[] v1 prat 637 porta mín 323 || div[] v1 prat 637 porta mín 323 || div[0.5] v2 prat 311/311 porta mín 160", "prateleira e portas até o final; o módulo certo não muda")
        XCTAssertEqual(o["faixaSome"] as? Bool, true)
        XCTAssertEqual(o["hist"] as? Bool, true, "a versão de antes fica no Histórico")
        XCTAssertEqual(o["desfez"] as? Bool, true)
        XCTAssertEqual(o["travado"] as? String, "1 módulo", "módulo travado fica de fora")
        XCTAssertEqual((o["errs"] as? [Any])?.count ?? 0, 0, "sem erros: \(o["errs"] ?? "")")
    }

    /// Catálogo Floraplac (Flora): 42 padrões com nome real, acabamento e textura do catálogo, no mesmo padrão das outras marcas.
    func testCatalogoFloraplacComNomesETexturasReais() async throws {
        let web = try await editor()
        let o = try await run(web, #"""
          window.MINI3OFF=1;PR.setupDone=1;S.mods=[];S.stones=[];S.fr=[];S.rp=[];S.env='cozinha';S.W=2400;S.H=2600;newTpl(3);var m=S.mods[0];S.m=m;draw();window.__cores('port');S.tab=10;panel();var R={};
          var F=MAT.filter(function(c){return c.f==='Floraplac'});R.total=MAT.length+' · Floraplac '+F.length+' ('+F.filter(function(c){return c.cat==='wood'}).length+' madeiras)';
          R.ids=F.every(function(c){return /^floraplac-[a-z0-9-]+$/.test(c.id)&&/^#[0-9a-f]{6}$/.test(c.hex)&&c.mm&&c.mm[0]>0&&c.mm[1]>0})&&new Set(MAT.map(function(c){return c.id})).size===MAT.length;
          R.nomes=F.map(function(c){return c.n}).join(', ');
          R.grupo=/Floraplac/.test(document.getElementById('bd').textContent);
          var q=document.querySelector('[data-csq="corF"]');q.value='nogueira nobre';q.dispatchEvent(new Event('input',{bubbles:true}));
          R.busca=[].filter.call(document.querySelectorAll('[data-csl="corF"] [data-cs]'),function(b){return !b.hidden}).map(function(b){return b.title});
          var b=document.querySelector('[data-csl="corF"] [data-cs*="floraplac-nogueira-nobre-natura"]');R.textura=b.getAttribute('data-bg')||(b.querySelector('[data-bg]')||{getAttribute:function(){return ''}}).getAttribute('data-bg');b.click();m=S.mods[0];
          R.aplicou=m.corFId+' · '+m.corFN+' · '+m.corF;
          R.corte=cutLines(m).filter(function(l){return /^Porta/.test((l.names||[])[0]||l.name||'')}).map(function(l){return l.colN})[0];
          /* as 42 imagens existem e carregam */
          var ok=0,bad=[];await Promise.all(F.map(function(c){return new Promise(function(r){var im=new Image();im.onload=function(){if(im.naturalWidth===512&&im.naturalHeight===512)ok++;else bad.push(c.id);r()};im.onerror=function(){bad.push(c.id);r()};im.src='cores/'+c.id+'.jpg'})}));R.imagens=ok+' ok '+bad.join(',');
          R.errs=window.__errs||[];return JSON.stringify(R);
          """#)
        XCTAssertEqual(o["total"] as? String, "239 · Floraplac 42 (19 madeiras)")
        XCTAssertEqual(o["ids"] as? Bool, true, "ids únicos, cor média e medida em todos")
        XCTAssertEqual(o["nomes"] as? String, "Adega, Âmago, Amêndoa, Convés, Geppetto, Lenho, Nogueira Nobre, Píer, Proa, Asfalto, City, Concrete, Carbon, Floresta, Magma, Rosé Gold, Sereno, Solar, Trama, Durban, Safira, Branco Aspro, Branco Nórdico, Cinza Cristal, Kiev, Viena, Fendi, Gouthier, Preto, Almeria, Barcelona, Freijó Natural, Nogal Amendoado, Carvalho Europeo, Castanea, Milano, Nogueira Imperial, Pau-Ferro Jucá, Copenhagen, Argos, Pietra Santa, Tesselati")
        XCTAssertEqual(o["grupo"] as? Bool, true, "a marca aparece no painel de cores")
        XCTAssertEqual(o["busca"] as? [String], ["Nogueira Nobre · Floraplac Natura"])
        XCTAssertEqual(o["textura"] as? String, "cores/floraplac-nogueira-nobre-natura.jpg")
        XCTAssertEqual(o["aplicou"] as? String, "floraplac-nogueira-nobre-natura · Nogueira Nobre · Floraplac Natura · #8e735d")
        XCTAssertEqual(o["corte"] as? String, "Nogueira Nobre · Floraplac Natura", "o nome da cor vai pro plano de corte")
        XCTAssertEqual(o["imagens"] as? String, "42 ok ", "as 42 texturas existem (512×512)")
        XCTAssertEqual((o["errs"] as? [Any])?.count ?? 0, 0, "sem erros: \(o["errs"] ?? "")")
    }

    /// Aba Portas: modelos com desenho — porta ripada (recorte + ripas por dentro), usinada (rasgos na peça) e palha, no 2D, no 3D e na lista de corte.
    func testPortaRipadaUsinadaEPalha() async throws {
        let web = try await editor()
        let o = try await run(web, #"""
          var W=function(ms){return new Promise(function(r){setTimeout(r,ms)})};PR.setupDone=1;var R={};
          S.room='cozinha';S.mods=[];newTpl(CATS[0].it[0]);var m=S.mods[0];m.x=300;m.w=1000;S.m=m;S.sv=0;draw();
          S.tab=3;panel();await W(80);
          var bd=document.getElementById('bd');R.cartoes=[].slice.call(bd.querySelectorAll('[data-vzm]')).map(function(b){return b.querySelector('b').textContent+(b.classList.contains('sel')?'*':'')}).join(' | ');
          var doors=function(){return partsOf(m).filter(function(p){return p.name==='Porta'})},rip=function(){return partsOf(m).filter(function(p){return /^Ripa da porta/.test(p.name)})};
          R.lisa=doors().map(function(p){return Math.round(p.w)+'x'+Math.round(p.h)+(p.vz?' vz':'')}).join(',');
          /* ripada vertical */
          bd.querySelector('[data-vzm="rip|v"]').click();await W(120);var d=doors()[0],G=d.vz;
          R.ripV=JSON.stringify(m.v[0].vz)+' · recorte '+G.win.join(',')+' · '+G.n+' ripas '+G.rw+'×'+G.len+' vão '+G.gp+' · peças de ripa '+rip().length+' ('+rip()[0].cl+'×'+rip()[0].cw+')';
          R.ripNota=(d.note||'').slice((d.note||'').indexOf('PORTA RIPADA'));
          R.ripSoma=Math.round((G.n*G.rw+(G.n+1)*G.gp)*10)/10+' = '+G.win[2];
          R.corte=cutLines(m).filter(function(l){return /Ripa da porta|^Porta/.test((l.names||[])[0]||l.name||'')}).map(function(l){return ((l.names||[])[0]||l.name)+' '+l.qty+'× '+l.L+'×'+l.W}).join(' | ');
          R.svg2d=document.querySelectorAll('#svg rect[fill="#26211c"]').length+' recortes no desenho';
          /* usinada vertical e horizontal */
          document.getElementById('bd').querySelector('[data-vzm="usi|v"]').click();await W(120);d=doors()[0];G=d.vz;
          R.usiV=G.n+' rasgos '+G.sw+'×'+G.len+' entre '+G.gp+' margem '+G.mg+' início '+G.ini+' · ripas '+rip().length+' · simétrico='+(Math.abs(G.holes[0][0]-(d.w-(G.holes[G.n-1][0]+G.sw)))<0.2);
          document.getElementById('bd').querySelector('[data-vzm="usi|h"]').click();await W(120);d=doors()[0];G=d.vz;R.usiH=G.d+' '+G.n+' rasgos '+G.sw+'×'+G.len;
          /* medida em Ajustes muda todas */
          var inp=document.getElementById('bd').querySelector('[data-vzs="vzUsiGap"]');inp.value='50';inp.dispatchEvent(new Event('change',{bubbles:true}));await W(120);R.ajuste=doors()[0].vz.n+' rasgos com 50 entre eles · guardou '+STD().vzUsiGap;
          STD().vzUsiGap=35;
          /* palha */
          document.getElementById('bd').querySelector('[data-vzm="pal|v"]').click();await W(120);d=doors()[0];G=d.vz;R.palha=JSON.stringify(m.v[0].vz)+' · recorte '+G.win.join(',')+' · tela '+G.tela.join('×')+' · ripas '+rip().length+' · '+(d.note||'').slice((d.note||'').indexOf('PORTA PALHA'));
          R.palha2d=document.querySelectorAll('#svg pattern').length+' tramas no desenho';
          /* 3D: sólidos com vão de verdade */
          document.getElementById('bd').querySelector('[data-vzm="rip|v"]').click();await W(100);
          var So=vzSolids(doors()[0].vz,doors()[0].w,doors()[0].h);var Fr=So.filter(function(q){return q[4]===0&&q[5]===15});R.solidos=Fr.length+' pedaços da frente sem linha='+Fr.every(function(q){return q[8]===3})+' · ripas atrás com linha '+So.filter(function(q){return q[4]<0&&q[8]!==3}).length+' · área frente '+Math.round(Fr.reduce(function(t,q){return t+(q[1]-q[0])*(q[3]-q[2])},0))+' = '+Math.round(doors()[0].w*doors()[0].h-doors()[0].vz.win[2]*doors()[0].vz.win[3]);
          open3D();await W(700);var bx=window.dbg3all?dbg3all():[];R.d3=bx.length>0?bx.filter(function(b){return /:Porta$/.test(String(b.nm||''))}).length+' caixas de porta no 3D':'sem dbg';
          document.getElementById('v3x').click();await W(100);
          /* volta pra lisa · salvar e reabrir mantém */
          var st=JSON.stringify(snapState());loadState(JSON.parse(st));draw();m=S.mods[0];S.m=m;R.reabriu=JSON.stringify(m.v[0].vz);
          S.tab=3;panel();await W(60);document.getElementById('bd').querySelector('[data-vzm="0"]').click();await W(100);R.voltou=doors().map(function(p){return p.vz?'vz':'lisa'}).join(',')+' ripas '+rip().length;
          /* Ajustes tem a seção */
          stdOpen(0);await W(120);R.ajustes=!!document.querySelector('#stdbody [data-vzaj]')+' '+document.querySelectorAll('#stdbody [data-vzs]').length+' campos';document.getElementById('stdm').hidden=true;
          R.errs=window.__errs||[];return JSON.stringify(R);
          """#)
        XCTAssertEqual(o["cartoes"] as? String, "Lisa* | Ripada vertical | Ripada horizontal | Usinada vertical | Usinada horizontal | Palha")
        XCTAssertEqual(o["lisa"] as? String, "490x705,490x705")
        XCTAssertEqual(o["ripV"] as? String, "{\"t\":\"rip\",\"d\":\"v\"} · recorte 90,220,310,345 · 4 ripas 45×405 vão 26 · peças de ripa 8 (405×45)")
        XCTAssertEqual(o["ripNota"] as? String, "PORTA RIPADA (vertical, ripas por dentro): recorte de 310 × 345 mm · a 90 das laterais, 220 de cima e 140 de baixo · 4 ripas de 45 × 405 fixadas por trás, 26 mm entre elas")
        XCTAssertEqual(o["ripSoma"] as? String, "310 = 310", "ripas + vãos fecham a largura do recorte")
        XCTAssertEqual(o["corte"] as? String, "Porta 2× 490×705 | Ripa da porta ripada 8× 405×45", "lista de corte: as portas e as ripas")
        XCTAssertEqual(o["svg2d"] as? String, "2 recortes no desenho")
        XCTAssertEqual(o["usiV"] as? String, "9 rasgos 12×584 entre 35 margem 50 início 51 · ripas 0 · simétrico=true")
        XCTAssertEqual(o["usiH"] as? String, "h 13 rasgos 12×390")
        XCTAssertEqual(o["ajuste"] as? String, "10 rasgos com 50 entre eles · guardou 50", "a medida vale pra todas e fica guardada")
        XCTAssertEqual(o["palha"] as? String, "{\"t\":\"pal\",\"d\":\"v\"} · recorte 70,70,350,565 · tela 380×595 · ripas 0 · PORTA PALHA: recorte de 350 × 565 mm no meio da porta · moldura de 70 mm em volta · tela de palhinha de 380 × 595 mm fixada por trás (passa 15 mm de cada lado)")
        XCTAssertEqual(o["solidos"] as? String, "4 pedaços da frente sem linha=true · ripas atrás com linha 4 · área frente 238500 = 238500", "3D: a porta é uma peça só (sem risco de emenda), a frente é a porta menos o recorte e as ripas ficam por trás")
        XCTAssertEqual(o["reabriu"] as? String, "{\"t\":\"rip\",\"d\":\"v\"}", "gravar e reabrir mantém o modelo")
        XCTAssertEqual(o["voltou"] as? String, "lisa,lisa ripas 0")
        XCTAssertEqual(o["ajustes"] as? String, "true 11 campos", "as medidas também ficam em Ajustes")
        XCTAssertEqual((o["errs"] as? [Any])?.count ?? 0, 0, "sem erros: \(o["errs"] ?? "")")
    }

