        /* salvar e reabrir mantém encostado · desfazer volta */
        loadState(JSON.parse(JSON.stringify(snapState())));m=S.mods[0];S.m=m;soloOn(m);draw();R.reabriu=Z()+' | '+V();
        /* puxa de volta: o vão abre de novo */
