        XCTAssertEqual(o["trocou"] as? String, "pendente do pf3 true · pf3 na biblioteca com a mexida true · pf5 na biblioteca com a mexida true · arquivos pequenos sobrando 0")
        XCTAssertEqual(o["errs"] as? Int, 0)
    }

