          if(red){for(var j=1;j<F.length;j++){red.click();await W(70);passos++;if(foto()!==F[j]){ruins.push('cen '+c+': refazer "'+N[j-1]+'" não ficou igual (passo '+j+' de '+N.join(' › ')+')');break}}}}
