        XCTAssertEqual(o["ruins"] as? String, "0")
        XCTAssertEqual(o["temRefazer"] as? Bool, true)
        XCTAssertEqual(o["errs"] as? Int, 0)
    }

    func testModuloDeBaixoSeAdaptaAAlturaDaPedraNaoEJogadoProLado() async throws {
