        var clicavel=function(e){for(var k=0,p=e;p&&p!==document.body&&k<4;k++,p=p.parentNode){if(/^(BUTTON|A|LABEL|SELECT|INPUT|SUMMARY)$/.test(p.tagName)||getComputedStyle(p).cursor==='pointer')return p}return null};
        var out=[],tot=0,enf=[];
