        XCTAssertEqual(o["divisoriasNoDesenho"] as? String, "3 peças · uma em cima da outra 0")
        XCTAssertEqual(o["maisOutra"] as? String, "3 divisórias · vãos 206,206,206,206 · door,door,drawers,drawers · menor vão 206")
